import{_ as a,o,c as r,a6 as i}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"Shopee SG：封面、规格与变体套图","description":"","frontmatter":{"id":"shopee-localization","title":"Shopee SG：封面、规格与变体套图","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"原创教程与规划示范，尚未执行图像任务或后台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","visual-copywriting","cross-border-knowledge"],"platform_rule_ids":["shopee"],"order":23.5},"headers":[],"relativePath":"ecommerce/shopee-localization.md","filePath":"ecommerce/shopee-localization.md"}'),t={name:"ecommerce/shopee-localization.md"};function l(s,e,p,h,n,c){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="shopee-sg-封面、规格与变体套图" tabindex="-1">Shopee SG：封面、规格与变体套图 <a class="header-anchor" href="#shopee-sg-封面、规格与变体套图" aria-label="Permalink to &quot;Shopee SG：封面、规格与变体套图&quot;">​</a></h1><p>本页以新加坡市场英文商品页为练习。其他市场的语言、位置和上传提示需另查。Shopee SG公开指导建议清晰实际商品、干净封面、规格和使用信息；这些是该页面的指导，不是所有市场、店铺类型的统一硬性规则。<a href="https://ads.shopee.sg/learn/faq/520/172" target="_blank" rel="noreferrer">SG官方商品页指导</a>。</p><h2 id="第1步-整理当地任务" tabindex="-1">第1步：整理当地任务 <a class="header-anchor" href="#第1步-整理当地任务" aria-label="Permalink to &quot;第1步：整理当地任务&quot;">​</a></h2><p>记录市场SG、商品DN01、页面位置、语言、变体、上传尺寸／体积要求、官方出处与核对时间。当前后台参数未提供时，先做可重排的方形母版；示范采用2000方图，属于制作建议。</p><p>官方SG指导建议至少1024×1024的方图及纯白封面。本页不据此填写全站图片数量、全部接口大小或其他地区限制。店铺特殊规范、上传提示和类目条件另核对。</p><h2 id="第2步-给套图分工" tabindex="-1">第2步：给套图分工 <a class="header-anchor" href="#第2步-给套图分工" aria-label="Permalink to &quot;第2步：给套图分工&quot;">​</a></h2><ol><li>封面：白底真实商品，清晰展示盒体与盖子，不叠无依据的促销标识。</li><li>结构：开盖和可拆隔板，用实际照片和准确短标签。</li><li>尺寸：220×150×120 mm外尺寸，标明长、宽、高；不把单位换算当测量。</li><li>配件：盒体1、盖子1、隔板1，文具道具不是套装内容。</li><li>场景：获准书桌使用情境，商品大小关系与光影可信。</li><li>变体：只展示清单中真实存在的SKU，颜色和型号不自行增加。</li></ol><p>这些是示范任务，实际上传张数以当地界面和商品需求安排。复制<a href="/ai-visual-creation-handbook/prompts/P15">P15 Shopee SG套图</a>，先输出任务表，再逐张处理。</p><h2 id="第3步-英文表达与变体检查" tabindex="-1">第3步：英文表达与变体检查 <a class="header-anchor" href="#第3步-英文表达与变体检查" aria-label="Permalink to &quot;第3步：英文表达与变体检查&quot;">​</a></h2><p>标题与短标签使用事实词，例如“Desk organizer with lid”“Removable divider”“What’s included”。“Waterproof”“Food-safe”“Eco-friendly”等在练习事实表中没有依据，不进入图片。</p><p>马来西亚或其他市场版本另使用<a href="/ai-visual-creation-handbook/prompts/P16">P16</a>设置目标语言，不把英文文案当全部市场答案。每个变体绑对应照片与实际规格，缺素材先列待补。</p><h2 id="第4步-核对真实页面" tabindex="-1">第4步：核对真实页面 <a class="header-anchor" href="#第4步-核对真实页面" aria-label="Permalink to &quot;第4步：核对真实页面&quot;">​</a></h2><p>查看手机首图、切换变体、图片顺序、文字、尺寸和发货内容。后台上传和平台审核状态单独记录。这里提供的是教程和完整模板，未实际进入Shopee后台上传。</p><p>Shopee关于视频AI内容的公开说明有自己的范围，不能自动变成静态商品图片规则；制作视频另核对对应入口。</p>',14)])])}const _=a(t,[["render",l]]);export{m as __pageData,_ as default};
